package com.bank.version.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
public class Account {
    @Id private String id;
    @Column(name = "holder_name") private String holderName;
    private BigDecimal balance;

    @Version private Long version;   // Hibernate manages this, never set by hand

    protected Account() {}
    public BigDecimal getBalance() { return balance; }
    public Long getVersion() { return version; }

    public void credit(BigDecimal amt) { this.balance = balance.add(amt); }
    public void debit(BigDecimal amt) {
        if (balance.compareTo(amt) < 0) throw new IllegalStateException("Insufficient funds");
        this.balance = balance.subtract(amt);
    }
}
