package com.bank.version.service;

import com.bank.version.model.Account;
import com.bank.version.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.*;
import java.math.BigDecimal;

@Component
@RequiredArgsConstructor
public class TransferTxn {
    private final AccountRepository repo;

    // Each attempt runs in a BRAND NEW transaction (REQUIRES_NEW)
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void debitOnce(String id, BigDecimal amount) {
        Account acc = repo.findById(id).orElseThrow();  // reads current version
        acc.debit(amount);                               // UPDATE ... WHERE version=?
        // on commit, if version changed → ObjectOptimisticLockingFailureException
    }
}
