package com.bank.version.service;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;

@Slf4j
@Service
@RequiredArgsConstructor
public class TransferService {
    private final TransferTxn txn;   // retry wrapper OUTSIDE the transaction

    public void debit(String id, BigDecimal amount) {
        int maxAttempts = 3;
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                txn.debitOnce(id, amount);   // fresh transaction each time
                log.info("Debit {} of {} succeeded on attempt {}", id, amount, attempt);
                return;
            } catch (ObjectOptimisticLockingFailureException e) {
                log.warning(() -> "Version conflict on " + id + ", attempt " + attempt);
                if (attempt == maxAttempts) {
                    log.severe("Debit failed after retries on " + id);
                    throw e;
                }
            }
        }
    }
}
